class SpecifiedStrategyAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.history_windows = {
            symbol: RollingWindow[TradeBar](101)
            for symbol in self.symbols.values()
        }

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        if self.is_warming_up:
            return

        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol not in data.bars:
                return
            bars[symbol] = data.bars[symbol]

        for symbol, bar in bars.items():
            self.history_windows[symbol].add(bar)

        if (
            not self.spy_sma.is_ready
            or not self.aapl_rsi.is_ready
            or any(not window.is_ready for window in self.history_windows.values())
        ):
            return

        spy_window = self.history_windows[self.spy]
        aapl_window = self.history_windows[self.aapl]

        spy_today_close = spy_window[0].close
        spy_yesterday_close = spy_window[1].close
        spy_sma_today = self.spy_sma.current.value
        spy_sma_yesterday = sum(spy_window[i].close for i in range(1, 101)) / 100

        aapl_today_close = aapl_window[0].close
        aapl_yesterday_close = aapl_window[1].close
        aapl_two_days_ago_close = aapl_window[2].close
        aapl_three_days_ago_close = aapl_window[3].close

        # Strategy A: SPY
        if self.strategy_a_shares > 0:
            if (
                spy_yesterday_close >= spy_sma_yesterday
                and spy_today_close < spy_sma_today
            ):
                self.market_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0
        else:
            if (
                spy_yesterday_close <= spy_sma_yesterday
                and spy_today_close > spy_sma_today
            ):
                target_value = self.portfolio.total_portfolio_value * 0.40
                quantity = int(target_value // spy_today_close)
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.strategy_a_shares = quantity

        # Strategy B: AAPL
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0
        else:
            three_consecutive_red_days = (
                aapl_today_close < aapl_yesterday_close
                and aapl_yesterday_close < aapl_two_days_ago_close
                and aapl_two_days_ago_close < aapl_three_days_ago_close
            )

            if three_consecutive_red_days and self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_today_close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.strategy_b_shares = quantity
