class ParallelSpyAaplStrategy(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.bars = {
            symbol: RollingWindow[TradeBar](101)
            for symbol in self.symbols.values()
        }

        self.spy_sma_values = RollingWindow[float](2)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        received = {}

        for symbol in self.symbols.values():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                received[symbol] = bar
                self.bars[symbol].add(bar)

                if symbol == self.spy:
                    self.spy_sma.update(bar.end_time, bar.close)
                    if self.spy_sma.is_ready:
                        self.spy_sma_values.add(float(self.spy_sma.current.value))

                elif symbol == self.aapl:
                    self.aapl_rsi.update(bar.end_time, bar.close)

        if len(received) != len(self.symbols):
            return

        if not self._all_rules_ready():
            return

        spy_close_today = float(received[self.spy].close)
        spy_close_yesterday = float(self.bars[self.spy][1].close)
        spy_sma_today = self.spy_sma_values[0]
        spy_sma_yesterday = self.spy_sma_values[1]

        aapl_close_today = float(received[self.aapl].close)
        aapl_close_yesterday = float(self.bars[self.aapl][1].close)
        aapl_close_two_days_ago = float(self.bars[self.aapl][2].close)
        aapl_close_three_days_ago = float(self.bars[self.aapl][3].close)

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )

        aapl_red_for_three_days = (
            aapl_close_today < aapl_close_yesterday
            and aapl_close_yesterday < aapl_close_two_days_ago
            and aapl_close_two_days_ago < aapl_close_three_days_ago
        )

        aapl_rsi_above_60 = float(self.aapl_rsi.current.value) > 60

        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.market_order(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0
        elif self.strategy_a_shares == 0 and spy_crosses_above:
            self.set_holdings(self.spy, 0.40)
            self.strategy_a_shares = self.portfolio[self.spy].quantity

        if self.strategy_b_shares > 0 and aapl_rsi_above_60:
            self.market_order(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0
        elif self.strategy_b_shares == 0 and aapl_red_for_three_days:
            if self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_close_today)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.strategy_b_shares = quantity

    def _all_rules_ready(self):
        return (
            self.bars[self.spy].count >= 101
            and self.bars[self.aapl].count >= 4
            and self.spy_sma.is_ready
            and self.spy_sma_values.count >= 2
            and self.aapl_rsi.is_ready
        )
