from collections import deque


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_closes = {ticker: None for ticker in self.symbols}
        self.aapl_red_streak = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities are updated continuously whenever data exists.
        if "SPY" in bars:
            self.previous_spy_close = self.previous_closes["SPY"]
            self.previous_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            self.spy_sma.Update(bars["SPY"].EndTime, bars["SPY"].Close)
            self.previous_closes["SPY"] = bars["SPY"].Close

        if "AAPL" in bars:
            previous_aapl_close = self.previous_closes["AAPL"]

            if previous_aapl_close is not None and bars["AAPL"].Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_rsi.Update(bars["AAPL"].EndTime, bars["AAPL"].Close)
            self.previous_closes["AAPL"] = bars["AAPL"].Close

        for ticker in ["IBM", "BAC", "AIG"]:
            if ticker in bars:
                self.previous_closes[ticker] = bars[ticker].Close

        # Skip all rule evaluation if any subscribed ticker is missing today.
        if len(bars) != len(self.symbols):
            return

        # Do not trade until every indicator used by a rule is fully formed.
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close
        spy_sma_value = self.spy_sma.Current.Value
        aapl_rsi_value = self.aapl_rsi.Current.Value

        # Slot 1 - Strategy A
        if self.strategy_a_shares == 0:
            if (self.previous_spy_close is not None and
                    self.previous_spy_sma is not None and
